import zlib,struct,sys
def load(p):
    d=open(p,'rb').read(); i=8; idat=b''; plte=None; trns=None
    while i<len(d):
        l,=struct.unpack('>I',d[i:i+4]); t=d[i+4:i+8]; c=d[i+8:i+8+l]; i+=12+l
        if t==b'IHDR': w,h,bd,ct,_,_,il=struct.unpack('>IIBBBBB',c)
        elif t==b'IDAT': idat+=c
        elif t==b'PLTE': plte=c
        elif t==b'tRNS': trns=c
    assert bd==8 and il==0, (bd,il,ct)
    ch={6:4,2:3,0:1,4:2,3:1}[ct]; raw=zlib.decompress(idat); s=w*ch; out=[]; prev=bytearray(s); p=0
    for y in range(h):
        f=raw[p]; line=bytearray(raw[p+1:p+1+s]); p+=1+s
        for x in range(s):
            a=line[x-ch] if x>=ch else 0; b=prev[x]; cc=prev[x-ch] if x>=ch else 0
            if f==1: line[x]=(line[x]+a)&255
            elif f==2: line[x]=(line[x]+b)&255
            elif f==3: line[x]=(line[x]+(a+b)//2)&255
            elif f==4:
                pp=a+b-cc; pa,pb,pc=abs(pp-a),abs(pp-b),abs(pp-cc)
                pr=a if pa<=pb and pa<=pc else (b if pb<=pc else cc); line[x]=(line[x]+pr)&255
        out.append(line); prev=line
    def alpha(x,y):
        px=out[y][x*ch:(x+1)*ch]
        if ct==6: return px[3]
        if ct==4: return px[1]
        if ct==3: return trns[px[0]] if trns and px[0]<len(trns) else 255
        return 255
    def rgba(x,y): return tuple(out[y][x*ch:(x+1)*ch])
    return w,h,alpha,rgba
def bboxes(p):
    w,h,alpha,_=load(p); res=[]
    for Y in range(0,h,32):
        for X in range(0,w,32):
            xs=[x for y in range(Y,Y+32) for x in range(X,X+32) if alpha(x,y)]
            ys=[y-Y for y in range(Y,Y+32) for x in range(X,X+32) if alpha(x,y)]
            res.append((min(xs)-X,min(ys),max(xs)-X,max(ys)) if xs else None)
    return res
if __name__=='__main__':
    for f in sys.argv[1:]: print(f, bboxes(f))
